class Counter:
    def __init__(self) -> None:
        self.value = 0

    def increment(self) -> None:
        self.value += 1

    def reset(self) -> None:
        self.value = 0


counter = Counter()
for command in input().split():
    if command == "inc":
        counter.increment()
    elif command == "reset":
        counter.reset()
print(counter.value)

