go.solution:
package main

import (
	"bufio"
	"fmt"
	"os"
)

// Go has no classes. A struct with methods plays the same role.
type Counter struct {
	value int
}

func (c *Counter) increment() {
	c.value++
}

func (c *Counter) reset() {
	c.value = 0
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	counter := Counter{}
	for scanner.Scan() {
		switch scanner.Text() {
		case "inc":
			counter.increment()
		case "reset":
			counter.reset()
		}
	}
	fmt.Println(counter.value)
}

